questionvariables.text:
mlist: [[12,7,11,3],[10,4,11,4],[9,11,6,5],[11,14,4,3],[14,8,5,4],[5,12,3,5],[13,9,4,3],[13,15,11,4],[4,7,6,5],[11,8,10,3]];
/* Design: find the mistake in an angle calculation. er 3: BC = p + q (triangle ABC treated as a straight path); er 4: the formula for the angle at B; er 5: inverse cosine in radians. Intermediate values shown to 2 d.p., the cosine to 4 d.p.; later steps carry the error. Steps 1 and 2 are never the mistake. Source: original. */
ix: 1+rand(10); MM: mlist[ix];
pp: MM[1]; qq: MM[2]; rr: MM[3]; er: MM[4];
LS: "ABCV"; LT: [[0,0,0],[pp,0,0],[0,qq,0],[0,0,rr]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
VB: dst("VB"); VC: dst("VC"); BC: dst("BC");
VBr: r2(VB); VCr: r2(VC); BCr: r2(BC); BCs: if er = 3 then pp+qq else BCr;
cs: if er = 4 then (VBr^2+BCs^2-VCr^2)/(2*VBr*BCs) else (VBr^2+VCr^2-BCs^2)/(2*VBr*VCr);
csr: float(floor(10000*cs+1/2)/10000);
shown: if er = 5 then float(acos(csr)) else float(acos(csr)*180/%pi); shr: r1(shown);
ok: angd("BVC"); csok: float(cos(ok*%pi/180));
vbc: if er = 4 then NA else angd("VBC"); vcb: angd("VCB"); radv: if er = 5 then NB else float(ok*%pi/180);
s2p: pp^2+rr^2; s2q: qq^2+rr^2; s2b: pp^2+qq^2;
opts: [["s1",false,"Step 1"],["s2",false,"Step 2"],["s3",is(er=3),"Step 3"],["s4",is(er=4),"Step 4"],["s5",is(er=5),"Step 5"]];
ta1: first(mcq_correct(opts)); gws: if er = 3 then "s4" else "s3";
okr: r1(ok); oka: ok+0.2; okg: ok+1.0; vcbr: r1(vcb);
